claimants = ['PAT_033','PAT_265','PAT_006']
for c in claimants:
    r=byid[c]
    print('='*70)
    print('CLAIMANT', c, r['full_name'], '|', r['compensation_reason'], '| surname:', r['second_name'])
    print('  its emergency contact:', desc(r['emergency_contact_patient_id']))
    print('  -- patients who list this claimant as THEIR emergency contact:')
    for x in rows:
        if x['emergency_contact_patient_id']==c:
            print('     ', desc(x['patient_id']))
"

