arguments.command:
python3 -c "
import csv
from collections import Counter, defaultdict
rows = list(csv.DictReader(open('dataset/hospital_compensation_registry.csv')))
byid = {r['patient_id']: r for r in rows}

# in-degree: who is named as emergency contact, and by whom
named_by = defaultdict(list)
for r in rows:
    named_by[r['emergency_contact_patient_id']].append(r['patient_id'])

death_claimants = {'PAT_033','PAT_265','PAT_006'}
death_surnames = {'Rivera','Quill','Jones'}

print('doc status dist:', Counter(r['documentation_status'] for r in rows if r['documentation_status']))
print('policy tier dist:', Counter(r['policy_tier'] for r in rows if r['policy_tier']))
print()
# For each no-claim patient, features
print('NO-CLAIM patients that are EC-linked to a death claimant (either direction):')
for r in rows:
    if r['record_date']: continue
    pid=r['patient_id']; sn=r['second_name']; ec=r['emergency_contact_patient_id']
    names_death = ec in death_claimants
    named_by_death = any(x in death_claimants for x in named_by.get(pid,[]))
    if names_death or named_by_death or sn in death_surnames:
        tag=[]
        if names_death: tag.append(f'EC->deathclaimant({ec})')
        if named_by_death: tag.append('named-by-deathclaimant('+','.join(x for x in named_by[pid] if x in death_claimants)+')')
        if sn in death_surnames: tag.append('death-surname:'+sn)
        print(f'  {pid} {r[\"full_name\"]:15s} indeg={len(named_by.get(pid,[]))}  ', '; '.join(tag))
"

